// Builds registry.json (shadcn registry schema) and showcase/theme.css from:
//   registry/facet/theme/tokens.json  (generated by gen-theme.mjs from Facet tokens)
//   registry/meta/<name>.json          (one per component: title, description, files)
// Dependencies are detected from each file's imports, so meta files only list extras.
import { readFileSync, writeFileSync, readdirSync, existsSync } from "node:fs"
import { join } from "node:path"

const root = new URL("..", import.meta.url).pathname
const tokens = JSON.parse(readFileSync(join(root, "registry/facet/theme/tokens.json"), "utf8"))
const SHADCN_STANDARD = new Set(["background","foreground","card","card-foreground","popover","popover-foreground","primary","primary-foreground","secondary","secondary-foreground","muted","muted-foreground","accent","accent-foreground","destructive","border","input","ring","chart-1","chart-2","chart-3","chart-4","chart-5","sidebar","sidebar-foreground","sidebar-primary","sidebar-primary-foreground","sidebar-accent","sidebar-accent-foreground","sidebar-border","sidebar-ring"])

const px = (v) => `${parseFloat(v) / 16}rem`
const light = { radius: px(tokens.radius), ...tokens.light }
const dark = { ...tokens.dark }
// Tailwind colour utilities for Facet extras (standard shadcn names are already mapped in every shadcn project).
const theme = Object.fromEntries(Object.keys(tokens.light).filter((k) => !SHADCN_STANDARD.has(k)).map((k) => [`color-${k}`, `var(--${k})`]))

// Facet's signature shape: every corner rounded except a tighter top-right.
const corner = (big, small) => `calc(var(--radius) * ${big}) calc(var(--radius) * ${small}) calc(var(--radius) * ${big}) calc(var(--radius) * ${big})`
const css = {
  "@utility rounded-facet-sm": { "border-radius": corner(0.75, 0.25) },
  "@utility rounded-facet": { "border-radius": corner(1, 0.25) },
  "@utility rounded-facet-lg": { "border-radius": corner(1.5, 0.5) },
  "@utility rounded-facet-xl": { "border-radius": corner(2, 0.75) },
  "@utility rounded-facet-2xl": { "border-radius": corner(3, 1) },
  "@keyframes facet-shimmer": { "0%": { "background-position": "200% 0" }, "100%": { "background-position": "-200% 0" } },
  "@keyframes facet-marquee": { from: { transform: "translateX(0)" }, to: { transform: "translateX(calc(-50% - var(--gap, 1rem) / 2))" } },
  "@keyframes facet-caret-blink": { "0%,70%,100%": { opacity: "1" }, "20%,50%": { opacity: "0" } },
}

const metaDir = join(root, "registry/meta")
const metas = readdirSync(metaDir).filter((f) => f.endsWith(".json")).sort().map((f) => JSON.parse(readFileSync(join(metaDir, f), "utf8")))
const typeOf = (p) => (p.startsWith("ui/") ? "registry:ui" : p.startsWith("hooks/") ? "registry:hook" : "registry:lib")
const PEER = new Set(["react", "react-dom"])

const problems = []
const items = metas.map((m) => {
  const deps = new Set(m.dependencies || [])
  const regDeps = new Set(["@facet/theme", ...(m.registryDependencies || [])])
  for (const rel of m.files) {
    const file = join(root, "registry/facet", rel)
    if (!existsSync(file)) { problems.push(`${m.name}: missing file ${rel}`); continue }
    const src = readFileSync(file, "utf8")
    for (const [, spec] of src.matchAll(/from\s+["']([^"']+)["']/g)) {
      if (spec.startsWith("@/registry/facet/ui/")) { const dep = spec.split("/").pop(); if (dep !== m.name) regDeps.add(`@facet/${dep}`) }
      else if (spec === "@/registry/facet/lib/utils") regDeps.add("utils")
      else if (spec === "@/registry/facet/lib/motion") regDeps.add("@facet/motion")
      else if (spec.startsWith("@/")) problems.push(`${m.name}: unsupported import ${spec}`)
      else if (!spec.startsWith(".")) { const pkg = spec.startsWith("@") ? spec.split("/").slice(0, 2).join("/") : spec.split("/")[0]; if (!PEER.has(pkg)) deps.add(pkg) }
    }
  }
  return {
    name: m.name, type: "registry:ui", title: m.title, description: m.description,
    ...(m.categories ? { categories: m.categories } : {}),
    dependencies: [...deps].sort(), registryDependencies: [...regDeps].sort(),
    files: m.files.map((p) => ({ path: `registry/facet/${p}`, type: typeOf(p) })),
  }
})
if (problems.length) { console.error(problems.join("\n")); process.exit(1) }

const registry = {
  $schema: "https://ui.shadcn.com/schema/registry.json",
  name: "facet",
  homepage: "https://facetui.vercel.app",
  items: [
    { name: "theme", type: "registry:theme", title: "Facet UI theme", description: "Facet UI colour, radius and motion tokens mapped onto shadcn variables (light + dark), plus the Facet corner utilities.", cssVars: { theme, light, dark }, css },
    { name: "motion", type: "registry:lib", title: "Facet motion presets", description: "Springs, easings and variants shared by every Facet component, plus <FacetMotion> for reduced-motion support.", dependencies: ["motion"], files: [{ path: "registry/facet/lib/motion.tsx", type: "registry:lib" }] },
    ...items,
    { name: "all", type: "registry:block", title: "Everything", description: "Every Facet UI React component in one command.", registryDependencies: items.map((i) => `@facet/${i.name}`) },
  ],
}
writeFileSync(join(root, "registry.json"), JSON.stringify(registry, null, 2) + "\n")

// Showcase stylesheet with the same values.
const decl = (o) => Object.entries(o).map(([k, v]) => `  --${k}: ${v};`).join("\n")
const block = (sel, body) => `${sel} {\n${Object.entries(body).map(([k, v]) => typeof v === "object" ? `  ${k} { ${Object.entries(v).map(([a, b]) => `${a}: ${b};`).join(" ")} }` : `  ${k}: ${v};`).join("\n")}\n}`
const std = [...SHADCN_STANDARD].map((k) => `  --color-${k}: var(--${k});`).join("\n")
const out = `/* Generated by scripts/sync-registry.mjs — do not edit. */
:root {
${decl(light)}
}
.dark {
${decl(dark)}
}
@theme inline {
${std}
${Object.entries(theme).map(([k, v]) => `  --${k}: ${v};`).join("\n")}
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
}
${Object.entries(css).map(([k, v]) => block(k, v)).join("\n")}
`
writeFileSync(join(root, "showcase/theme.css"), out)
console.log(`registry.json: ${registry.items.length} items (${items.length} components)`)
